mapper.select:
SELECT 
    id, user_id, message_type, title, content, 
    related_id, related_type, is_read, read_time,
    created_time, updated_time, deleted
FROM user_message
WHERE user_id = #{userId}
AND deleted = 0

    AND message_type = #{messageType}


    AND is_read = #{isRead}

ORDER BY created_time DESC

mapper.update:
UPDATE user_message
SET is_read = 1, read_time = NOW()
WHERE user_id = #{userId}
AND deleted = 0

    AND message_type = #{messageType}
